-- AUTO-GENERATED by pnpm gen-onboarding from libs/db/onboarding/*. Do not edit by hand.

-- Global onboarding thread + note content reconcile (affects all users).
-- Threads are authored by the system Plot twist instance and routed via the
-- @plot.updates auto-maintained announce topic (the @plot.updates topic is how
-- every user receives them — file_thread_priority_for_topic_members files them).
DO $$
DECLARE
    c_system_instance_id CONSTANT uuid := '0199b6f4-ae64-7718-0000-000000000001';
    c_twist_package_id CONSTANT uuid := '0199b6f4-ae64-7718-8a02-44716f30358f';
    v_plot_twist_id bigint;
    v_updates_topic_id uuid;
    v_thread_id uuid;
    v_note_id uuid;
BEGIN
    SELECT id INTO v_plot_twist_id FROM public.twist
        WHERE twist_package_id = c_twist_package_id AND environment = 'public' LIMIT 1;
    SELECT id INTO v_updates_topic_id FROM public.topic
        WHERE key = '@plot.updates' AND auto_maintained = TRUE AND team_id IS NULL LIMIT 1;
    -- Atlas-robust: skip on fresh DBs where the system twist / topic isn't seeded yet.
    IF v_plot_twist_id IS NULL OR v_updates_topic_id IS NULL THEN RETURN; END IF;

    -- welcome
    SELECT id INTO v_thread_id FROM public.thread
        WHERE key = 'welcome' AND twist_id = v_plot_twist_id AND archived_at IS NULL LIMIT 1;
    IF v_thread_id IS NULL THEN
        -- topic_id (not just the topic text) is what file_thread_priority_for_topic_members
        -- keys on — without it new users never get the thread filed / never see it.
        INSERT INTO public.thread (created_by, twist_id, icon, title, preview, key, topic_id, topic, contacts)
            VALUES (c_system_instance_id, v_plot_twist_id, 'twist:' || v_plot_twist_id::text,
                'Everything in its place', 'Plot is designed around a simple workflow that keeps your focus where you choose while knowing what''s happening.', 'welcome', v_updates_topic_id, 'topic:' || v_updates_topic_id::text,
                ARRAY[c_system_instance_id])
        RETURNING id INTO v_thread_id;
    ELSE
        UPDATE public.thread SET title = 'Everything in its place', preview = 'Plot is designed around a simple workflow that keeps your focus where you choose while knowing what''s happening.',
                topic_id = v_updates_topic_id, topic = 'topic:' || v_updates_topic_id::text
            WHERE id = v_thread_id
              AND (title, preview, topic_id) IS DISTINCT FROM ('Everything in its place', 'Plot is designed around a simple workflow that keeps your focus where you choose while knowing what''s happening.', v_updates_topic_id);
    END IF;
    SELECT id INTO v_note_id FROM public.note
        WHERE thread_id = v_thread_id AND key = 'building-blocks' AND link_id IS NULL AND archived_at IS NULL LIMIT 1;
    IF v_note_id IS NULL THEN
        INSERT INTO public.note (author_id, created_by, thread_id, source_created_at, content, key)
            VALUES (c_system_instance_id, c_system_instance_id, v_thread_id, now() + (0 * interval '1 minute'), 'Plot is designed around a simple workflow that keeps your focus where you choose while knowing
what''s happening.

New and updated threads arrive at the top of **Active**. _When a thread…_

- _… is just FYI_: Simply read it and it''ll move to **Done**.
- _… needs follow-up or careful reading_: Mark it **To do** to keep it in **Active**.
- _… deserves attention later_: Mark it **Do later** to move it out of **Active** until a future
  day.
- _… belongs in another focus_: **Move** it. Plot learns and moves similar threads there in the
  future.
- _… never needs attention_: **Mute** it. You can always find threads in Done or with search, but
  muted threads (and similar ones) will skip **Active**.

Instead of interruptions fragmenting your day, you can trust that everything gets done at the best
time.', 'building-blocks');
    ELSE
        UPDATE public.note SET content = 'Plot is designed around a simple workflow that keeps your focus where you choose while knowing
what''s happening.

New and updated threads arrive at the top of **Active**. _When a thread…_

- _… is just FYI_: Simply read it and it''ll move to **Done**.
- _… needs follow-up or careful reading_: Mark it **To do** to keep it in **Active**.
- _… deserves attention later_: Mark it **Do later** to move it out of **Active** until a future
  day.
- _… belongs in another focus_: **Move** it. Plot learns and moves similar threads there in the
  future.
- _… never needs attention_: **Mute** it. You can always find threads in Done or with search, but
  muted threads (and similar ones) will skip **Active**.

Instead of interruptions fragmenting your day, you can trust that everything gets done at the best
time.'
            WHERE id = v_note_id AND content IS DISTINCT FROM 'Plot is designed around a simple workflow that keeps your focus where you choose while knowing
what''s happening.

New and updated threads arrive at the top of **Active**. _When a thread…_

- _… is just FYI_: Simply read it and it''ll move to **Done**.
- _… needs follow-up or careful reading_: Mark it **To do** to keep it in **Active**.
- _… deserves attention later_: Mark it **Do later** to move it out of **Active** until a future
  day.
- _… belongs in another focus_: **Move** it. Plot learns and moves similar threads there in the
  future.
- _… never needs attention_: **Mute** it. You can always find threads in Done or with search, but
  muted threads (and similar ones) will skip **Active**.

Instead of interruptions fragmenting your day, you can trust that everything gets done at the best
time.';
    END IF;
    SELECT id INTO v_note_id FROM public.note
        WHERE thread_id = v_thread_id AND key = 'focuses' AND link_id IS NULL AND archived_at IS NULL LIMIT 1;
    IF v_note_id IS NULL THEN
        INSERT INTO public.note (author_id, created_by, thread_id, source_created_at, content, key)
            VALUES (c_system_instance_id, c_system_instance_id, v_thread_id, now() + (1 * interval '1 minute'), 'By bringing all you work together, Plot eliminates time and attention lost to jump around tools.
Instead of organizing your work by _where_ it is, you organize it by _how_ you work on it. This lets
you make real progress in an area you choose.

Create focuses for:

- _Important projects_: With everything related to a project in one focus, you can find what you
  need quickly, with a clear view of what''s outstanding. Even better, you can send related messages
  and replies without getting pulled into unrelated work that happens to be in the same chat, inbox,
  or app.
- _Core responsibilities_: At work, you might have direct responsibilities while also managing
  others. Putting these in separate focuses ensures you make progress on your goals while giving
  your team the attention they deserve.
- _Key activities_: Certain activities are done best with concentrated focus, like customer and
  sales conversations, or reviewing progress from a large team. In a focus, you choose how much and
  how often to invest your time.

Focuses aren''t just for your most important priorities. By creating focuses for low-urgency
activities like unsolicited requests, you can batch them to complete efficiently less frequently.

Focuses are grouped within roles. Add a role for each areas of your life, such as work, personal,
and volunteering. Roles help you stay on top of commitments that easily get buried by your biggest
role.', 'focuses');
    ELSE
        UPDATE public.note SET content = 'By bringing all you work together, Plot eliminates time and attention lost to jump around tools.
Instead of organizing your work by _where_ it is, you organize it by _how_ you work on it. This lets
you make real progress in an area you choose.

Create focuses for:

- _Important projects_: With everything related to a project in one focus, you can find what you
  need quickly, with a clear view of what''s outstanding. Even better, you can send related messages
  and replies without getting pulled into unrelated work that happens to be in the same chat, inbox,
  or app.
- _Core responsibilities_: At work, you might have direct responsibilities while also managing
  others. Putting these in separate focuses ensures you make progress on your goals while giving
  your team the attention they deserve.
- _Key activities_: Certain activities are done best with concentrated focus, like customer and
  sales conversations, or reviewing progress from a large team. In a focus, you choose how much and
  how often to invest your time.

Focuses aren''t just for your most important priorities. By creating focuses for low-urgency
activities like unsolicited requests, you can batch them to complete efficiently less frequently.

Focuses are grouped within roles. Add a role for each areas of your life, such as work, personal,
and volunteering. Roles help you stay on top of commitments that easily get buried by your biggest
role.'
            WHERE id = v_note_id AND content IS DISTINCT FROM 'By bringing all you work together, Plot eliminates time and attention lost to jump around tools.
Instead of organizing your work by _where_ it is, you organize it by _how_ you work on it. This lets
you make real progress in an area you choose.

Create focuses for:

- _Important projects_: With everything related to a project in one focus, you can find what you
  need quickly, with a clear view of what''s outstanding. Even better, you can send related messages
  and replies without getting pulled into unrelated work that happens to be in the same chat, inbox,
  or app.
- _Core responsibilities_: At work, you might have direct responsibilities while also managing
  others. Putting these in separate focuses ensures you make progress on your goals while giving
  your team the attention they deserve.
- _Key activities_: Certain activities are done best with concentrated focus, like customer and
  sales conversations, or reviewing progress from a large team. In a focus, you choose how much and
  how often to invest your time.

Focuses aren''t just for your most important priorities. By creating focuses for low-urgency
activities like unsolicited requests, you can batch them to complete efficiently less frequently.

Focuses are grouped within roles. Add a role for each areas of your life, such as work, personal,
and volunteering. Roles help you stay on top of commitments that easily get buried by your biggest
role.';
    END IF;
    SELECT id INTO v_note_id FROM public.note
        WHERE thread_id = v_thread_id AND key = 'notifications' AND link_id IS NULL AND archived_at IS NULL LIMIT 1;
    IF v_note_id IS NULL THEN
        INSERT INTO public.note (author_id, created_by, thread_id, source_created_at, content, key)
            VALUES (c_system_instance_id, c_system_instance_id, v_thread_id, now() + (2 * interval '1 minute'), '**Notifications** let you choose when updates in a focus should interrupt you based on how quickly
you need know about them. For many, your best move is to turn notifications off and schedule the
right time for the focus. For others, set how quickly and the times they are sent to maintain your
desired response time. While you can get an immediate notification for everything, every time you
choose to silence or batch notifications, you gain focus for what is more important each day.', 'notifications');
    ELSE
        UPDATE public.note SET content = '**Notifications** let you choose when updates in a focus should interrupt you based on how quickly
you need know about them. For many, your best move is to turn notifications off and schedule the
right time for the focus. For others, set how quickly and the times they are sent to maintain your
desired response time. While you can get an immediate notification for everything, every time you
choose to silence or batch notifications, you gain focus for what is more important each day.'
            WHERE id = v_note_id AND content IS DISTINCT FROM '**Notifications** let you choose when updates in a focus should interrupt you based on how quickly
you need know about them. For many, your best move is to turn notifications off and schedule the
right time for the focus. For others, set how quickly and the times they are sent to maintain your
desired response time. While you can get an immediate notification for everything, every time you
choose to silence or batch notifications, you gain focus for what is more important each day.';
    END IF;

    -- getting-around
    SELECT id INTO v_thread_id FROM public.thread
        WHERE key = 'getting-around' AND twist_id = v_plot_twist_id AND archived_at IS NULL LIMIT 1;
    IF v_thread_id IS NULL THEN
        -- topic_id (not just the topic text) is what file_thread_priority_for_topic_members
        -- keys on — without it new users never get the thread filed / never see it.
        INSERT INTO public.thread (created_by, twist_id, icon, title, preview, key, topic_id, topic, contacts)
            VALUES (c_system_instance_id, v_plot_twist_id, 'twist:' || v_plot_twist_id::text,
                'Getting Around', 'Keyboard and touch shortcuts', 'getting-around', v_updates_topic_id, 'topic:' || v_updates_topic_id::text,
                ARRAY[c_system_instance_id])
        RETURNING id INTO v_thread_id;
    ELSE
        UPDATE public.thread SET title = 'Getting Around', preview = 'Keyboard and touch shortcuts',
                topic_id = v_updates_topic_id, topic = 'topic:' || v_updates_topic_id::text
            WHERE id = v_thread_id
              AND (title, preview, topic_id) IS DISTINCT FROM ('Getting Around', 'Keyboard and touch shortcuts', v_updates_topic_id);
    END IF;
    SELECT id INTO v_note_id FROM public.note
        WHERE thread_id = v_thread_id AND key = 'intro' AND link_id IS NULL AND archived_at IS NULL LIMIT 1;
    IF v_note_id IS NULL THEN
        INSERT INTO public.note (author_id, created_by, thread_id, source_created_at, content, key)
            VALUES (c_system_instance_id, c_system_instance_id, v_thread_id, now() + (0 * interval '1 minute'), 'Plot''s goal is to get you to meaningful work as quickly as possible. Here are some tips for navigating efficiently.', 'intro');
    ELSE
        UPDATE public.note SET content = 'Plot''s goal is to get you to meaningful work as quickly as possible. Here are some tips for navigating efficiently.'
            WHERE id = v_note_id AND content IS DISTINCT FROM 'Plot''s goal is to get you to meaningful work as quickly as possible. Here are some tips for navigating efficiently.';
    END IF;
    SELECT id INTO v_note_id FROM public.note
        WHERE thread_id = v_thread_id AND key = 'keyboard' AND link_id IS NULL AND archived_at IS NULL LIMIT 1;
    IF v_note_id IS NULL THEN
        INSERT INTO public.note (author_id, created_by, thread_id, source_created_at, content, key)
            VALUES (c_system_instance_id, c_system_instance_id, v_thread_id, now() + (1 * interval '1 minute'), '**Keyboard Navigation**

- **⌘N** (Ctrl+N on Windows, ⌘⌃N / Ctrl+Alt+N on web browsers): Create a new note
- **⌘/** (Ctrl+/ on Windows): Search across all your threads and focuses
- **⌘K** (Ctrl+K on Windows): Open the command palette
- **⌘J** (Ctrl+J on Windows, ⌘⌃J / Ctrl+Alt+J on web browsers): Switch to another focus
- **⌘D** (Ctrl+D on Windows): To do / Done — toggle whether this thread requires action
- **⌘⇧D** (Ctrl+Shift+D on Windows): Schedule a thread to do later
- **⌘Up/Down** (Ctrl+Up/Down on Windows): Open previous/next thread
- **⌘Enter** (Ctrl+Enter on Windows): When adding a note, mark it (and the thread) to do', 'keyboard');
    ELSE
        UPDATE public.note SET content = '**Keyboard Navigation**

- **⌘N** (Ctrl+N on Windows, ⌘⌃N / Ctrl+Alt+N on web browsers): Create a new note
- **⌘/** (Ctrl+/ on Windows): Search across all your threads and focuses
- **⌘K** (Ctrl+K on Windows): Open the command palette
- **⌘J** (Ctrl+J on Windows, ⌘⌃J / Ctrl+Alt+J on web browsers): Switch to another focus
- **⌘D** (Ctrl+D on Windows): To do / Done — toggle whether this thread requires action
- **⌘⇧D** (Ctrl+Shift+D on Windows): Schedule a thread to do later
- **⌘Up/Down** (Ctrl+Up/Down on Windows): Open previous/next thread
- **⌘Enter** (Ctrl+Enter on Windows): When adding a note, mark it (and the thread) to do'
            WHERE id = v_note_id AND content IS DISTINCT FROM '**Keyboard Navigation**

- **⌘N** (Ctrl+N on Windows, ⌘⌃N / Ctrl+Alt+N on web browsers): Create a new note
- **⌘/** (Ctrl+/ on Windows): Search across all your threads and focuses
- **⌘K** (Ctrl+K on Windows): Open the command palette
- **⌘J** (Ctrl+J on Windows, ⌘⌃J / Ctrl+Alt+J on web browsers): Switch to another focus
- **⌘D** (Ctrl+D on Windows): To do / Done — toggle whether this thread requires action
- **⌘⇧D** (Ctrl+Shift+D on Windows): Schedule a thread to do later
- **⌘Up/Down** (Ctrl+Up/Down on Windows): Open previous/next thread
- **⌘Enter** (Ctrl+Enter on Windows): When adding a note, mark it (and the thread) to do';
    END IF;
    SELECT id INTO v_note_id FROM public.note
        WHERE thread_id = v_thread_id AND key = 'touch' AND link_id IS NULL AND archived_at IS NULL LIMIT 1;
    IF v_note_id IS NULL THEN
        INSERT INTO public.note (author_id, created_by, thread_id, source_created_at, content, key)
            VALUES (c_system_instance_id, c_system_instance_id, v_thread_id, now() + (2 * interval '1 minute'), '**Touch Gestures**

- **Long press** on items to drag and reorder
- **Swipe right** on threads: To do
- **Swipe right (long)** on threads: Schedule to do later
- **Swipe left** on threads: Done
- **Swipe left (long)** on items to open a menu with all commands', 'touch');
    ELSE
        UPDATE public.note SET content = '**Touch Gestures**

- **Long press** on items to drag and reorder
- **Swipe right** on threads: To do
- **Swipe right (long)** on threads: Schedule to do later
- **Swipe left** on threads: Done
- **Swipe left (long)** on items to open a menu with all commands'
            WHERE id = v_note_id AND content IS DISTINCT FROM '**Touch Gestures**

- **Long press** on items to drag and reorder
- **Swipe right** on threads: To do
